import { useEffect, useState } from "react";
import { io } from "socket.io-client";

const socket = io("http://localhost:5000");

function AdminDashboard() {

  const [queues, setQueues] = useState([]);

  const fetchQueues = async () => {

    const res = await fetch(
      "http://localhost:5000/api/queue/all"
    );

    const data = await res.json();

    setQueues(data);

    // notify next 3 patients
    const currentPatient =
      data.findIndex(
        q => q.status === "InQueue"
      );

    if(currentPatient !== -1){

      const nextPatients =
        data.slice(
          currentPatient + 1,
          currentPatient + 4
        );

      nextPatients.forEach(patient => {

        socket.emit(
          "queueNear",
          {
            patientName:
              patient.patientName
          }
        );

      });

    }

  };

  useEffect(()=>{

    fetchQueues();

    socket.on(
      "queueUpdated",
      fetchQueues
    );

    return ()=>{
      socket.off(
        "queueUpdated"
      );
    };

  },[]);

  const confirmOP = async(id)=>{

    await fetch(
      `http://localhost:5000/api/queue/confirm/${id}`,
      {
        method:"PUT"
      }
    );

    fetchQueues();

  };

  const completeOP = async(id)=>{

    await fetch(
      `http://localhost:5000/api/queue/complete/${id}`,
      {
        method:"DELETE"
      }
    );

    setQueues(
      prev =>
      prev.filter(
        q =>
        q._id !== id
      )
    );

  };

  return(

    <div style={{padding:20}}>

      <h2>
        👨‍⚕️ Admin Dashboard
      </h2>

      {
        queues.map(q=>(

          <div
            key={q._id}

            style={{
              border:
              "1px solid black",
              margin:10,
              padding:10
            }}
          >

            <p>
              Patient:
              {q.patientName}
            </p>

            <p>
              Department:
              {q.department}
            </p>

            <p>
              Status:
              {q.status}
            </p>

            {
              q.status==="Waiting" && (

                <button
                  onClick={()=>
                    confirmOP(
                      q._id
                    )
                  }
                >
                  Confirm OP
                </button>

              )
            }

            <button

              onClick={()=>
                completeOP(
                  q._id
                )
              }

            >
              Complete OP
            </button>

          </div>

        ))
      }

    </div>

  );

}

export default AdminDashboard;
